const STEPS = [
  { value: "info", title: "Información" },
  { value: "address", title: "Dirección" },
  { value: "payment", title: "Pago" },
]

function Wizard() {
  const [step, setStep] = useState("info")
  const [completed, setCompleted] = useState<string[]>([])

  const navigateTo = (next: string) => {
    const newIndex = STEPS.findIndex(s => s.value === next)
    setCompleted(STEPS.slice(0, newIndex).map(s => s.value))
    setStep(next)
  }

  const index = STEPS.findIndex(s => s.value === step)

  return (
    <div className="flex flex-col gap-6">
      <Stepper value={step} onValueChange={navigateTo} completedSteps={completed} clickable="all">
        <StepperList>
          {STEPS.map(s => (
            <StepperItem key={s.value} value={s.value} title={s.title} />
          ))}
        </StepperList>
      </Stepper>

      {/* Step content panel */}
      <div>{/* render current step UI */}</div>

      <div className="flex justify-between">
        <Button variant="outline" disabled={index === 0} onClick={() => navigateTo(STEPS[index - 1]!.value)}>Anterior</Button>
        <Button disabled={index === STEPS.length - 1} onClick={() => navigateTo(STEPS[index + 1]!.value)}>Siguiente</Button>
      </div>
    </div>
  )
}
